@php $nxAnnouncement=null; try { if(\Illuminate\Support\Facades\Schema::hasTable('announcements')) $nxAnnouncement=\Illuminate\Support\Facades\DB::table('announcements')->where('active',true)->where(function($q){$q->whereNull('starts_at')->orWhere('starts_at','<=',now());})->where(function($q){$q->whereNull('ends_at')->orWhere('ends_at','>=',now());})->orderByDesc('id')->first(); } catch(\Throwable $e) {} @endphp @if($nxAnnouncement)<div class="nx-announcement nx-announcement-{{$nxAnnouncement->type}}"><div><strong>{{$nxAnnouncement->title}}</strong><span>{{$nxAnnouncement->message}}</span></div>@if($nxAnnouncement->button_text && $nxAnnouncement->button_url)<a href="{{$nxAnnouncement->button_url}}" rel="noopener">{{$nxAnnouncement->button_text}} →</a>@endif</div><style>.nx-announcement{position:relative;z-index:1050;display:flex;align-items:center;justify-content:center;gap:18px;padding:10px 16px;background:#12304a;border-bottom:1px solid #24577e;color:#fff;font:13px/1.4 Inter,system-ui,sans-serif;text-align:center}.nx-announcement strong{margin-right:8px}.nx-announcement a{color:#fff;font-weight:800;text-decoration:underline;white-space:nowrap}.nx-announcement-success{background:#0c4937;border-color:#1d765a}.nx-announcement-warning{background:#5a4010;border-color:#8b671e}.nx-announcement-danger{background:#5a1e29;border-color:#8b3041}@media(max-width:650px){.nx-announcement{flex-direction:column;gap:5px;padding:9px 12px}.nx-announcement strong,.nx-announcement span{display:block;margin:0}}</style>@endif